import { ChallanStatus, MovementType } from '@prisma/client';
import { AppError } from '../middleware/errorHandler';

export async function confirmChallan(client: any, challanId: string, user: { userId: string; role: string }) {
  const challan = await client.challan.findUnique({ where: { id: challanId }, include: { lineItems: true } });
  if (!challan) throw new AppError(404, 'Challan not found');
  if (user.role === 'Sales' && challan.createdBy !== user.userId) throw new AppError(403, 'Insufficient permissions to confirm this challan');
  return client.$transaction(async (tx: any) => {
    const { count } = await tx.challan.updateMany({ where: { id: challan.id, status: ChallanStatus.Draft }, data: { status: ChallanStatus.Confirmed } });
    if (count !== 1) throw new AppError(400, 'Only draft challans can be confirmed');
    for (const item of challan.lineItems) {
      const product = await tx.product.findUnique({ where: { id: item.productId } });
      if (!product || product.currentStock < item.quantity) throw new AppError(400, `Insufficient stock for ${item.productId}`);
      await tx.stockMovement.create({ data: { productId: item.productId, quantityChanged: item.quantity, movementType: MovementType.OUT, reason: challan.challanNumber, createdBy: user.userId } });
      await tx.product.update({ where: { id: item.productId }, data: { currentStock: { decrement: item.quantity } } });
    }
    return tx.challan.findUnique({ where: { id: challan.id }, include: { lineItems: true } });
  });
}

import { Router } from 'express';
import { z } from 'zod';
import { ChallanStatus, MovementType } from '@prisma/client';
import { prisma } from '../lib/prisma';
import { authenticate, authorize } from '../middleware/auth';
import { validateBody, AppError, getPagination, paramId } from '../middleware/errorHandler';
import { generateInvoicePDF } from '../lib/pdfGenerator';

const router = Router();

const lineItemSchema = z.object({
  productId: z.string().uuid(),
  quantity: z.number().int().positive('Quantity must be a positive integer'),
});

const challanSchema = z.object({
  customerId: z.string().uuid(),
  lineItems: z.array(lineItemSchema).min(1, 'At least one line item is required'),
});

const challanUpdateSchema = z.object({
  customerId: z.string().uuid().optional(),
  lineItems: z.array(lineItemSchema).min(1).optional(),
});

async function generateChallanNumber(): Promise<string> {
  const year = new Date().getFullYear();
  const prefix = `CH-${year}-`;

  const lastChallan = await prisma.challan.findFirst({
    where: { challanNumber: { startsWith: prefix } },
    orderBy: { challanNumber: 'desc' },
  });

  let nextNum = 1;
  if (lastChallan) {
    const parts = lastChallan.challanNumber.split('-');
    nextNum = parseInt(parts[2], 10) + 1;
  }

  return `${prefix}${String(nextNum).padStart(4, '0')}`;
}

async function buildLineItems(lineItems: { productId: string; quantity: number }[]) {
  const consolidatedMap = new Map<string, number>();
  for (const item of lineItems) {
    consolidatedMap.set(
      item.productId,
      (consolidatedMap.get(item.productId) || 0) + item.quantity
    );
  }
  const consolidated = Array.from(consolidatedMap.entries()).map(([productId, quantity]) => ({
    productId,
    quantity,
  }));

  const products = await Promise.all(
    consolidated.map((item) => prisma.product.findUnique({ where: { id: item.productId } }))
  );

  return consolidated.map((item, index) => {
    const product = products[index];
    if (!product) throw new AppError(400, `Product not found: ${item.productId}`);
    return {
      productId: product.id,
      productNameSnapshot: product.name,
      skuSnapshot: product.sku,
      unitPriceSnapshot: product.unitPrice,
      quantity: item.quantity,
    };
  });
}

router.use(authenticate);

router.post('/', authorize('manage_challans'), validateBody(challanSchema), async (req, res, next) => {
  try {
    const customer = await prisma.customer.findUnique({ where: { id: req.body.customerId } });
    if (!customer) throw new AppError(404, 'Customer not found');

    const builtItems = await buildLineItems(req.body.lineItems);
    const totalQuantity = builtItems.reduce((sum, item) => sum + item.quantity, 0);
    const challanNumber = await generateChallanNumber();

    const challan = await prisma.challan.create({
      data: {
        challanNumber,
        customerId: req.body.customerId,
        totalQuantity,
        status: ChallanStatus.Draft,
        createdBy: req.user!.userId,
        lineItems: { create: builtItems },
      },
      include: {
        lineItems: true,
        customer: { select: { id: true, name: true, businessName: true } },
        creator: { select: { id: true, name: true } },
      },
    });

    res.status(201).json(challan);
  } catch (error) {
    next(error);
  }
});

router.get('/', async (req, res, next) => {
  try {
    const { page, limit, skip } = getPagination(req.query);
    const status = req.query.status as ChallanStatus | undefined;
    const customerId = req.query.customerId as string | undefined;

    const where: Record<string, unknown> = {};
    if (status && Object.values(ChallanStatus).includes(status)) {
      where.status = status;
    }
    if (customerId) {
      where.customerId = customerId;
    }

    if (req.user!.role === 'Sales') {
      where.createdBy = req.user!.userId;
    }

    const canViewAll = ['Admin', 'Sales', 'Accounts'].includes(req.user!.role);
    if (!canViewAll) {
      throw new AppError(403, 'Insufficient permissions');
    }

    const [challans, total] = await Promise.all([
      prisma.challan.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdDate: 'desc' },
        include: {
          customer: { select: { id: true, name: true, businessName: true } },
          creator: { select: { id: true, name: true } },
          lineItems: true,
        },
      }),
      prisma.challan.count({ where }),
    ]);

    res.json({
      data: challans,
      pagination: { page, limit, total, totalPages: Math.ceil(total / limit) },
    });
  } catch (error) {
    next(error);
  }
});

router.get('/:id', async (req, res, next) => {
  try {
    const canView = ['Admin', 'Sales', 'Accounts'].includes(req.user!.role);
    if (!canView) throw new AppError(403, 'Insufficient permissions');

    const challan = await prisma.challan.findUnique({
      where: { id: paramId(req.params.id) },
      include: {
        customer: true,
        creator: { select: { id: true, name: true } },
        lineItems: true,
      },
    });

    if (!challan) throw new AppError(404, 'Challan not found');

    if (req.user!.role === 'Sales' && challan.createdBy !== req.user!.userId) {
      throw new AppError(403, 'Insufficient permissions');
    }

    res.json(challan);
  } catch (error) {
    next(error);
  }
});

router.put('/:id', authorize('manage_challans'), validateBody(challanUpdateSchema), async (req, res, next) => {
  try {
    const existing = await prisma.challan.findUnique({
      where: { id: paramId(req.params.id) },
      include: { lineItems: true },
    });

    if (!existing) throw new AppError(404, 'Challan not found');
    if (req.user!.role === 'Sales' && existing.createdBy !== req.user!.userId) {
      throw new AppError(403, 'Insufficient permissions to modify this challan');
    }
    if (existing.status !== ChallanStatus.Draft) {
      throw new AppError(400, 'Only draft challans can be edited');
    }

    if (req.body.customerId) {
      const customer = await prisma.customer.findUnique({ where: { id: req.body.customerId } });
      if (!customer) throw new AppError(404, 'Customer not found');
    }

    const updateData: Record<string, unknown> = {};
    if (req.body.customerId) updateData.customerId = req.body.customerId;

    if (req.body.lineItems) {
      const builtItems = await buildLineItems(req.body.lineItems);
      updateData.totalQuantity = builtItems.reduce((sum, item) => sum + item.quantity, 0);

      await prisma.challanLineItem.deleteMany({ where: { challanId: existing.id } });
      updateData.lineItems = { create: builtItems };
    }

    const challan = await prisma.challan.update({
      where: { id: paramId(req.params.id) },
      data: updateData,
      include: {
        lineItems: true,
        customer: { select: { id: true, name: true, businessName: true } },
        creator: { select: { id: true, name: true } },
      },
    });

    res.json(challan);
  } catch (error) {
    next(error);
  }
});

router.post('/:id/confirm', authorize('manage_challans'), async (req, res, next) => {
  try {
    const challan = await prisma.challan.findUnique({
      where: { id: paramId(req.params.id) },
      include: { lineItems: true },
    });

    if (!challan) throw new AppError(404, 'Challan not found');
    if (req.user!.role === 'Sales' && challan.createdBy !== req.user!.userId) {
      throw new AppError(403, 'Insufficient permissions to confirm this challan');
    }
    if (challan.status !== ChallanStatus.Draft) {
      throw new AppError(400, 'Only draft challans can be confirmed');
    }

    const lineItems = challan.lineItems;

    const result = await prisma.$transaction(async (tx) => {
      // Aggregate quantities per product to prevent multi-line stock check bypass
      const productQuantities = new Map<string, number>();
      for (const item of lineItems) {
        productQuantities.set(
          item.productId,
          (productQuantities.get(item.productId) || 0) + item.quantity
        );
      }

      for (const [productId, totalRequested] of productQuantities.entries()) {
        const product = await tx.product.findUnique({ where: { id: productId } });
        if (!product) {
          throw new AppError(400, `Product not found: ${productId}`);
        }
        if (totalRequested > product.currentStock) {
          throw new AppError(
            400,
            `Insufficient stock for ${product.name}. Available: ${product.currentStock}, Total Requested: ${totalRequested}`
          );
        }
      }

      for (const item of lineItems) {
        await tx.stockMovement.create({
          data: {
            productId: item.productId,
            quantityChanged: item.quantity,
            movementType: MovementType.OUT,
            reason: challan.challanNumber,
            createdBy: req.user!.userId,
          },
        });

        await tx.product.update({
          where: { id: item.productId },
          data: { currentStock: { decrement: item.quantity } },
        });
      }

      return tx.challan.update({
        where: { id: challan.id },
        data: { status: ChallanStatus.Confirmed },
        include: {
          lineItems: true,
          customer: { select: { id: true, name: true, businessName: true } },
          creator: { select: { id: true, name: true } },
        },
      });
    });

    res.json(result);
  } catch (error) {
    next(error);
  }
});

router.post('/:id/cancel', authorize('manage_challans'), async (req, res, next) => {
  try {
    const challan = await prisma.challan.findUnique({ where: { id: paramId(req.params.id) } });
    if (!challan) throw new AppError(404, 'Challan not found');

    if (req.user!.role === 'Sales' && challan.createdBy !== req.user!.userId) {
      throw new AppError(403, 'Insufficient permissions to cancel this challan');
    }

    if (challan.status === ChallanStatus.Cancelled) {
      throw new AppError(400, 'Challan is already cancelled');
    }

    if (challan.status === ChallanStatus.Confirmed) {
      throw new AppError(400, 'Confirmed challans cannot be cancelled');
    }

    const updated = await prisma.challan.update({
      where: { id: paramId(req.params.id) },
      data: { status: ChallanStatus.Cancelled },
      include: {
        lineItems: true,
        customer: { select: { id: true, name: true, businessName: true } },
        creator: { select: { id: true, name: true } },
      },
    });

    res.json(updated);
  } catch (error) {
    next(error);
  }
});

// PDF Invoice Generation
router.get('/:id/invoice', async (req, res, next) => {
  try {
    const canView = ['Admin', 'Sales', 'Accounts'].includes(req.user!.role);
    if (!canView) throw new AppError(403, 'Insufficient permissions');

    const challan = await prisma.challan.findUnique({
      where: { id: paramId(req.params.id) },
      include: {
        customer: true,
        creator: { select: { name: true } },
        lineItems: true,
      },
    });

    if (!challan) throw new AppError(404, 'Challan not found');

    if (req.user!.role === 'Sales' && challan.createdBy !== req.user!.userId) {
      throw new AppError(403, 'Insufficient permissions');
    }

    // Only allow PDF generation for confirmed challans
    if (challan.status !== ChallanStatus.Confirmed) {
      throw new AppError(400, 'Only confirmed challans can be exported as invoices');
    }

    // Set response headers for PDF download
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader(
      'Content-Disposition',
      `attachment; filename=invoice-${challan.challanNumber}.pdf`
    );

    // Generate and stream PDF
    generateInvoicePDF(challan, res);
  } catch (error) {
    next(error);
  }
});

export default router;

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { confirmChallan } from './challanConfirm';

// In-memory stand-in for Prisma with real-database concurrency semantics:
// every operation yields to the event loop first (so two concurrent
// confirmChallan calls interleave exactly like two concurrent HTTP requests),
// while updateMany's check-and-set runs synchronously and is therefore atomic,
// like a single SQL UPDATE ... WHERE status = 'Draft'.
function createFakePrisma() {
  const state = {
    challans: new Map([
      [
        'challan-1',
        {
          id: 'challan-1',
          challanNumber: 'CH-2026-0001',
          status: 'Draft',
          createdBy: 'user-1',
          lineItems: [{ productId: 'product-1', quantity: 3 }],
        },
      ],
    ]),
    products: new Map([
      ['product-1', { id: 'product-1', name: 'Widget', currentStock: 10 }],
    ]),
    movements: [] as { productId: string; quantityChanged: number }[],
  };

  const tick = () => new Promise<void>((resolve) => setImmediate(resolve));

  interface FakeTx {
    product: {
      findUnique(args: any): Promise<any>;
      update(args: any): Promise<any>;
    };
    stockMovement: {
      create(args: any): Promise<any>;
    };
    challan: {
      updateMany(args: any): Promise<{ count: number }>;
      update(args: any): Promise<any>;
      findUnique(args: any): Promise<any>;
    };
  }

  const tx: FakeTx = {
    product: {
      async findUnique({ where }: any) {
        await tick();
        return state.products.get(where.id) ?? null;
      },
      async update({ where, data }: any) {
        await tick();
        const product = state.products.get(where.id)!;
        product.currentStock += data.currentStock.decrement
          ? -data.currentStock.decrement
          : data.currentStock;
        return product;
      },
    },
    stockMovement: {
      async create({ data }: any) {
        await tick();
        state.movements.push({
          productId: data.productId,
          quantityChanged: data.quantityChanged,
        });
        return data;
      },
    },
    challan: {
      // Atomic compare-and-swap: no await between the status check and the
      // write, so concurrent transactions cannot both observe Draft.
      async updateMany({ where, data }: any) {
        await tick();
        const challan = state.challans.get(where.id);
        if (challan && challan.status === where.status) {
          challan.status = data.status;
          return { count: 1 };
        }
        return { count: 0 };
      },
      async update({ where, data }: any) {
        await tick();
        const challan = state.challans.get(where.id)!;
        Object.assign(challan, data);
        return challan;
      },
      async findUnique({ where }: any) {
        await tick();
        return state.challans.get(where.id) ?? null;
      },
    },
  };

  return {
    state,
    client: {
      challan: {
        async findUnique({ where }: any) {
          await tick();
          return state.challans.get(where.id) ?? null;
        },
      },
      // Shared state across concurrent transactions (read-committed-like).
      // A throwing transaction undoes only its own writes via a per-tx undo
      // log, like a real rollback: before-images are captured at the moment
      // this transaction writes, so restoring them cannot clobber another
      // transaction's committed changes.
      async $transaction<T>(fn: (tx: FakeTx) => Promise<T>): Promise<T> {
        const undoStatuses = new Map<string, string>();
        const undoStocks = new Map<string, number>();
        let createdMovements = 0;
        const trackedTx: FakeTx = {
          product: {
            findUnique: tx.product.findUnique,
            async update(args: any) {
              if (!undoStocks.has(args.where.id)) {
                undoStocks.set(args.where.id, state.products.get(args.where.id)!.currentStock);
              }
              return tx.product.update(args);
            },
          },
          stockMovement: {
            async create(args: any) {
              createdMovements += 1;
              return tx.stockMovement.create(args);
            },
          },
          challan: {
            async updateMany(args: any) {
              const result = await tx.challan.updateMany(args);
              // Only a matched row was actually written; its before-image is
              // the status the WHERE clause matched on.
              if (result.count > 0 && !undoStatuses.has(args.where.id)) {
                undoStatuses.set(args.where.id, args.where.status);
              }
              return result;
            },
            async update(args: any) {
              const challan = state.challans.get(args.where.id)!;
              if (!undoStatuses.has(challan.id)) {
                undoStatuses.set(challan.id, challan.status);
              }
              return tx.challan.update(args);
            },
            findUnique: tx.challan.findUnique,
          },
        };
        try {
          return await fn(trackedTx);
        } catch (error) {
          for (const [id, status] of undoStatuses) {
            state.challans.get(id)!.status = status;
          }
          for (const [id, stock] of undoStocks) {
            state.products.get(id)!.currentStock = stock;
          }
          state.movements.splice(state.movements.length - createdMovements, createdMovements);
          throw error;
        }
      },
    },
  };
}

describe('concurrent challan confirmation', () => {
  it('decrements stock exactly once when two confirms race', async () => {
    const { state, client } = createFakePrisma();
    const user = { userId: 'user-1', role: 'Admin' };

    const outcomes = await Promise.allSettled([
      confirmChallan(client, 'challan-1', user),
      confirmChallan(client, 'challan-1', user),
    ]);

    const fulfilled = outcomes.filter((o) => o.status === 'fulfilled');
    const rejected = outcomes.filter((o) => o.status === 'rejected');

    // Exactly one confirm wins; the loser is told the challan is no longer a draft.
    assert.strictEqual(fulfilled.length, 1);
    assert.strictEqual(rejected.length, 1);
    assert.match(
      (rejected[0] as PromiseRejectedResult).reason.message,
      /Only draft challans can be confirmed/
    );

    // Stock was decremented once (10 -> 7), not twice (10 -> 4).
    assert.strictEqual(state.products.get('product-1')!.currentStock, 7);
    assert.strictEqual(state.movements.length, 1);
    assert.strictEqual(state.challans.get('challan-1')!.status, 'Confirmed');
  });
});
